window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-355025c39493a03a"]={"versions": [{"id": "FIG-355025c39493a03a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Software Architecture Diagram) auf Ebene der Application Layer / Software-Composition.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release R4.0.3), Spezifikation <code>AUTOSAR_EXP_AIChassis</code> (Application Interfaces Chassis Domain). Das Diagramm modelliert die Zerlegung der Sub-Funktion <em>Cruise Control</em> (Tempomat / Konstantfahrregelung) als Stand-Alone-Variante (<code>stand-alone free cruise control</code>) innerhalb der übergeordneten Software-Composition <code>CrsCtrlAndAcc</code>, d. h. ohne Abstandsregelungskomponenten (ACC-Radarsensorik, Umfeldbeobachtung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>«CompositionSwComponentType»</code>):</strong> Kapselnde Composition für Geschwindigkeitsregelung und -überwachung.</li>\n<li><strong>Interne Komponenten (<code>«ApplicationSwComponentType»</code> Prototypen):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code>: Zustandsautomat und Modusverwaltung (Cruise Control State Control: Zustände wie <em>Off</em>, <em>Standby</em>, <em>Active</em>, <em>Override</em>).</li>\n<li><code>CrsCrtlFree</code> <em>(Diagramm-Schreibweise)</em>: Kern-Regelungsalgorithmus für die freie Geschwindigkeitsregelung (Soll-/Ist-Vergleich, Reglerberechnung ohne Abstandsführung).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code>: Beobachter und Signalaufbereitung für den dynamischen Fahrzeugzustand (Vehicle State Observer: Aggregation von Geschwindigkeit, Beschleunigung, Raddrehzahlen, Schlupf).</li>\n<li><strong>Externe Komponenten / Domänen (Interaktionspartner):</strong></li>\n<li><code>WPII-10.5 (HMI)</code>: Bedien- und Anzeigeschnittstelle (Lenkradtasten, Hebel: <em>Set</em>, <em>Resume</em>, <em>Cancel</em>, Display-Rückmeldung).</li>\n<li><code>WPII-10.1 (Body) Esc Epb ....</code>: Karosserie- und Bremssystemzustände (Schalterstellungen, Tür-/Gurtstatus, Bremslichtschalter, Parkbremsenstatus).</li>\n<li><code>WPII-10.2 (Powertrain) Esc Epb ....</code>: Antriebs- und Fahrdynamikstatus (Motormoment, Getriebegang, Kupplung, ESC-/ABS-Eingriffe).</li>\n<li><code>Vlc</code>: <em>Vehicle Longitudinal Control</em> (Längsführungs-Koordinator zur Ansteuerung von Antrieb und Bremsaktuatorik).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Connectors</p>\n<ul class=\"fig-list\">\n<li><strong>Ports (<code>P-Port</code> / <code>R-Port</code>):</strong> Quadratische Port-Konnektoren an den Schnittstellenbegrenzungen für Sender-Receiver-Kommunikation.</li>\n<li><strong>AssemblyConnectors (intern):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code> $\\leftrightarrow$ <code>CrsCrtlFree</code>: Übertragung des Betriebsmodus, Aktivierungsstatus und der Ziel-Setzgeschwindigkeit.</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> $\\rightarrow$ <code>CrsCrtlFree</code>: Bereitstellung des konsolidierten Fahrzeugzustands (gefilterte Ist-Geschwindigkeit, Fahrzeugdynamikdaten).</li>\n<li><strong>DelegationConnectors (Composition-Grenze):</strong></li>\n<li><code>WPII-10.5 (HMI)</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Fahrerbefehle.</li>\n<li><code>WPII-10.1 (Body)</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Sicherheitsabschaltungs-Signale (z. B. Bremspedalschalter).</li>\n<li><code>WPII-10.2 (Powertrain)</code> $\\rightarrow$ <code>CrsCtrlAndAccObsvrForVehSt</code>: Sensordaten / Status von Motor, Getriebe und ESC.</li>\n<li><code>CrsCrtlFree</code> $\\rightarrow$ <code>Vlc</code>: Sollbeschleunigung / Soll-Vortriebskraft an den Längsführungskoordinator.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Signalaufnahme & Zustandsbeobachtung (zyklisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liest zyklisch Antriebs- und Fahrwerksdaten von <code>WPII-10.2</code> ein, filtert Raddrehzahlen und plausibilisiert die Fahrzeuglängsgeschwindigkeit.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrerinteraktion & Modusumschaltung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedieneingaben über <code>WPII-10.5</code> triggern in <code>CrsCtrlAndAccStCtrl</code> Zustandswechsel (z. B. Wechsel von <em>Standby</em> auf <em>Active</em> bei Tastendruck <em>Set</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelungsfreigabe & Stellgrößenberechnung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CrsCtrlAndAccStCtrl</code> übergibt die Sollgeschwindigkeit und Freigabeflags an <code>CrsCrtlFree</code>.</li>\n<li><code>CrsCrtlFree</code> berechnet die Regeldifferenz ($\\Delta v = v_{\\text{set}} - v_{\\text{act}}$) unter Berücksichtigung der Dynamikdaten aus <code>CrsCtrlAndAccObsvrForVehSt</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausgabe an Aktorik-Koordination:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CrsCrtlFree</code> sendet die resultierende Längsbeschleunigungsanforderung ($a_{\\text{target}}$) an die externe SW-C <code>Vlc</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch- / Sicherheitsbedingungen (Fail-Safe):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Plötzliche Bremsbetätigung (<code>WPII-10.1</code>), Kupplungsbetätigung oder aktive Fahrdynamikeingriffe (<code>ESC</code> via <code>WPII-10.2</code>) führen in <code>CrsCtrlAndAccStCtrl</code> zur sofortigen Deaktivierung (Übergang in <em>Standby</em>) und zum Zurücksetzen der Stellgrößenanforderung an <code>Vlc</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>VFB-Unabhängigkeit:</strong> Alle dargestellten Schnittstellen basieren auf standardisierten AUTOSAR Application Interfaces (WPII-Katalog). Die Komponenten kommunizieren ausschließlich über RTE-Sender-Receiver-Interfaces; eine ECU-Allokation ist nicht vorgegeben (SW-Cs können auf einer oder verteilt auf mehreren ECUs deployed werden).</li>\n<li><strong>Variantenmanagement:</strong> Die Architektur zeigt das Pattern zur Variantenbildung: Für Voll-ACC wird die Composition um Radardatenverarbeitung und eine Abstandsregler-SW-C (<code>CrsCtrlAccFree</code> / <code>AccHeadwayCtrl</code>) erweitert, während die HMI-, Zustands- und Beobachterstrukturen weitgehend wiederverwendet werden.</li>\n<li><strong>RTE-Vertrag:</strong></li>\n<li>Datenelemente müssen für deterministisches Verhalten typischerweise mit <code>read-on-demand</code> bzw. zyklisch getakteten Runnables (Task-Perioden meist 10 ms bis 20 ms für Längsführung) konfiguriert werden.</li>\n<li><code>Vlc</code> agiert als Arbiter; <code>CrsCrtlFree</code> darf keine direkten Antriebsstrang- oder Brems-Aktuator-APIs ansteuern, sondern nur normalisierte Beschleunigungswünsche übergeben.</li>\n</ul>"}, {"id": "FIG-8285daab6fde4628", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Software Architecture Diagram) auf Ebene der Application Layer / Software-Composition.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release R4.1.3), Spezifikation <code>AUTOSAR_EXP_AIChassis</code> (Application Interfaces Chassis Domain). Das Diagramm modelliert die Zerlegung der Sub-Funktion <em>Cruise Control</em> (Tempomat / Konstantfahrregelung) als Stand-Alone-Variante (<code>stand-alone free cruise control</code>) innerhalb der übergeordneten Software-Composition <code>CrsCtrlAndAcc</code>, d. h. ohne Abstandsregelungskomponenten (ACC-Radarsensorik, Umfeldbeobachtung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>«CompositionSwComponentType»</code>):</strong> Kapselnde Composition für Geschwindigkeitsregelung und -überwachung.</li>\n<li><strong>Interne Komponenten (<code>«ApplicationSwComponentType»</code> Prototypen):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code>: Zustandsautomat und Modusverwaltung (Cruise Control State Control: Zustände wie <em>Off</em>, <em>Standby</em>, <em>Active</em>, <em>Override</em>).</li>\n<li><code>CrsCrtlFree</code> <em>(Diagramm-Schreibweise)</em>: Kern-Regelungsalgorithmus für die freie Geschwindigkeitsregelung (Soll-/Ist-Vergleich, Reglerberechnung ohne Abstandsführung).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code>: Beobachter und Signalaufbereitung für den dynamischen Fahrzeugzustand (Vehicle State Observer: Aggregation von Geschwindigkeit, Beschleunigung, Raddrehzahlen, Schlupf).</li>\n<li><strong>Externe Komponenten / Domänen (Interaktionspartner):</strong></li>\n<li><code>Multimedia Telematics HMI Domain</code>: Bedien- und Anzeigeschnittstelle (Lenkradtasten, Hebel: <em>Set</em>, <em>Resume</em>, <em>Cancel</em>, Display-Rückmeldung).</li>\n<li><code>Body Electronics Domain Esc Epb ....</code>: Karosserie- und Bremssystemzustände (Schalterstellungen, Tür-/Gurtstatus, Bremslichtschalter, Parkbremsenstatus).</li>\n<li><code>Powertrain Domain Esc Epb ....</code>: Antriebs- und Fahrdynamikstatus (Motormoment, Getriebegang, Kupplung, ESC-/ABS-Eingriffe).</li>\n<li><code>Vlc</code>: <em>Vehicle Longitudinal Control</em> (Längsführungs-Koordinator zur Ansteuerung von Antrieb und Bremsaktuatorik).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Connectors</p>\n<ul class=\"fig-list\">\n<li><strong>Ports (<code>P-Port</code> / <code>R-Port</code>):</strong> Quadratische Port-Konnektoren an den Schnittstellenbegrenzungen für Sender-Receiver-Kommunikation.</li>\n<li><strong>AssemblyConnectors (intern):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code> $\\leftrightarrow$ <code>CrsCrtlFree</code>: Übertragung des Betriebsmodus, Aktivierungsstatus und der Ziel-Setzgeschwindigkeit.</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> $\\rightarrow$ <code>CrsCrtlFree</code>: Bereitstellung des konsolidierten Fahrzeugzustands (gefilterte Ist-Geschwindigkeit, Fahrzeugdynamikdaten).</li>\n<li><strong>DelegationConnectors (Composition-Grenze):</strong></li>\n<li><code>Multimedia Telematics HMI Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Fahrerbefehle.</li>\n<li><code>Body Electronics Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Sicherheitsabschaltungs-Signale (z. B. Bremspedalschalter).</li>\n<li><code>Powertrain Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccObsvrForVehSt</code>: Sensordaten / Status von Motor, Getriebe und ESC.</li>\n<li><code>CrsCrtlFree</code> $\\rightarrow$ <code>Vlc</code>: Sollbeschleunigung / Soll-Vortriebskraft an den Längsführungskoordinator.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Signalaufnahme & Zustandsbeobachtung (zyklisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liest zyklisch Antriebs- und Fahrwerksdaten von der <code>Powertrain Domain</code> ein, filtert Raddrehzahlen und plausibilisiert die Fahrzeuglängsgeschwindigkeit.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrerinteraktion & Modusumschaltung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedieneingaben über die <code>Multimedia Telematics HMI Domain</code> triggern in <code>CrsCtrlAndAccStCtrl</code> Zustandswechsel (z. B. Wechsel von <em>Standby</em> auf <em>Active</em>, Setzen einer Wunschgeschwindigkeit).</li>\n<li>Status- und Abschaltbedingungen aus der <code>Body Electronics Domain</code> (z. B. Bremspedalbetätigung, Feststellbremse) führen zum sofortigen Übergang in den Zustand <em>Standby</em> oder <em>Off</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelungsberechnung & Aktoranforderung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei aktivem Zustand übergibt <code>CrsCtrlAndAccStCtrl</code> Sollwert und Regelstatus an <code>CrsCrtlFree</code>.</li>\n<li><code>CrsCrtlFree</code> ermittelt anhand des von <code>CrsCtrlAndAccObsvrForVehSt</code> bereitgestellten Fahrzeugzustands die Regelabweichung und sendet entsprechende Längsbeschleunigungs- bzw. Verzögerungsanforderungen an <code>Vlc</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>VFB-Unabhängigkeit:</strong> Alle dargestellten Schnittstellen basieren auf standardisierten AUTOSAR Application Interfaces (WPII-Katalog). Die Komponenten kommunizieren ausschließlich über RTE-Sender-Receiver-Interfaces; eine ECU-Allokation ist nicht vorgegeben (SW-Cs können auf einer oder verteilt auf mehreren ECUs deployed werden).</li>\n<li><strong>Variantenmanagement:</strong> Die Architektur zeigt das Pattern zur Variantenbildung: Für Voll-ACC wird die Composition um Radardatenverarbeitung und eine Abstandsregler-SW-C (<code>CrsCtrlAccFree</code> / <code>AccHeadwayCtrl</code>) erweitert, während die HMI-, Zustands- und Beobachterstrukturen weitgehend wiederverwendet werden.</li>\n<li><strong>RTE-Vertrag:</strong></li>\n<li>Datenelemente müssen für deterministisches Verhalten typischerweise mit <code>read-on-demand</code> bzw. zyklisch getakteten Runnables (Task-Perioden meist 10 ms bis 20 ms für Längsführung) konfiguriert werden.</li>\n<li><code>Vlc</code> agiert als Arbiter; <code>CrsCrtlFree</code> darf keine direkten Antriebsstrang- oder Brems-Aktuator-APIs ansteuern, sondern nur normalisierte Beschleunigungswünsche übergeben.</li>\n</ul>"}, {"id": "FIG-d2d029a5882d44aa", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm (Software Architecture Diagram) auf Ebene der Application Layer / Software-Composition.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release R4.1.3), Spezifikation <code>AUTOSAR_EXP_AIChassis</code> (Application Interfaces Chassis Domain). Das Diagramm modelliert die Zerlegung der Sub-Funktion <em>Cruise Control</em> (Tempomat / Konstantfahrregelung) als Stand-Alone-Variante (<code>stand-alone free cruise control</code>) innerhalb der übergeordneten Software-Composition <code>CrsCtrlAndAcc</code>, d. h. ohne Abstandsregelungskomponenten (ACC-Radarsensorik, Umfeldbeobachtung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Software-Components (SW-Cs)</p>\n<ul class=\"fig-list\">\n<li><strong><code>CrsCtrlAndAcc SW-Composition</code> (<code>«CompositionSwComponentType»</code>):</strong> Kapselnde Composition für Geschwindigkeitsregelung und -überwachung.</li>\n<li><strong>Interne Komponenten (<code>«ApplicationSwComponentType»</code> Prototypen):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code>: Zustandsautomat und Modusverwaltung (Cruise Control State Control: Zustände wie <em>Off</em>, <em>Standby</em>, <em>Active</em>, <em>Override</em>).</li>\n<li><code>CrsCrtlFree</code> <em>(Diagramm-Schreibweise)</em>: Kern-Regelungsalgorithmus für die freie Geschwindigkeitsregelung (Soll-/Ist-Vergleich, Reglerberechnung ohne Abstandsführung).</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code>: Beobachter und Signalaufbereitung für den dynamischen Fahrzeugzustand (Vehicle State Observer: Aggregation von Geschwindigkeit, Beschleunigung, Raddrehzahlen, Schlupf).</li>\n<li><strong>Externe Komponenten / Domänen (Interaktionspartner):</strong></li>\n<li><code>Multimedia Telematics HMI Domain</code>: Bedien- und Anzeigeschnittstelle (Lenkradtasten, Hebel: <em>Set</em>, <em>Resume</em>, <em>Cancel</em>, Display-Rückmeldung).</li>\n<li><code>Body Electronics Domain Esc Epb ....</code>: Karosserie- und Bremssystemzustände (Schalterstellungen, Tür-/Gurtstatus, Bremslichtschalter, Parkbremsenstatus).</li>\n<li><code>Powertrain Domain Esc Epb ....</code>: Antriebs- und Fahrdynamikstatus (Motormoment, Getriebegang, Kupplung, ESC-/ABS-Eingriffe).</li>\n<li><code>Vlc</code>: <em>Vehicle Longitudinal Control</em> (Längsführungs-Koordinator zur Ansteuerung von Antrieb und Bremsaktuatorik).</li>\n</ul>\n<p class=\"fig-p\">#### Ports & Connectors</p>\n<ul class=\"fig-list\">\n<li><strong>Ports (<code>P-Port</code> / <code>R-Port</code>):</strong> Quadratische Port-Konnektoren an den Schnittstellenbegrenzungen für Sender-Receiver-Kommunikation.</li>\n<li><strong>AssemblyConnectors (intern):</strong></li>\n<li><code>CrsCtrlAndAccStCtrl</code> $\\leftrightarrow$ <code>CrsCrtlFree</code>: Übertragung des Betriebsmodus, Aktivierungsstatus und der Ziel-Setzgeschwindigkeit.</li>\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> $\\rightarrow$ <code>CrsCrtlFree</code>: Bereitstellung des konsolidierten Fahrzeugzustands (gefilterte Ist-Geschwindigkeit, Fahrzeugdynamikdaten).</li>\n<li><strong>DelegationConnectors (Composition-Grenze):</strong></li>\n<li><code>Multimedia Telematics HMI Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Fahrerbefehle.</li>\n<li><code>Body Electronics Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccStCtrl</code>: Sicherheitsabschaltungs-Signale (z. B. Bremspedalschalter).</li>\n<li><code>Powertrain Domain</code> $\\rightarrow$ <code>CrsCtrlAndAccObsvrForVehSt</code>: Sensordaten / Status von Motor, Getriebe und ESC.</li>\n<li><code>CrsCrtlFree</code> $\\rightarrow$ <code>Vlc</code>: Sollbeschleunigung / Soll-Vortriebskraft an den Längsführungskoordinator.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Signalaufnahme & Zustandsbeobachtung (zyklisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CrsCtrlAndAccObsvrForVehSt</code> liest zyklisch Antriebs- und Fahrwerksdaten von der <code>Powertrain Domain</code> ein, filtert Raddrehzahlen und plausibilisiert die Fahrzeuglängsgeschwindigkeit.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrerinteraktion & Modusumschaltung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedieneingaben über die <code>Multimedia Telematics HMI Domain</code> triggern in <code>CrsCtrlAndAccStCtrl</code> Zustandswechsel (z. B. Wechsel von <em>Standby</em> auf <em>Active</em>, Setzen einer Wunschgeschwindigkeit).</li>\n<li>Status- und Abschaltbedingungen aus der <code>Body Electronics Domain</code> (z. B. Bremspedalbetätigung, Feststellbremse) führen zum sofortigen Übergang in den Zustand <em>Standby</em> oder <em>Off</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Regelungsberechnung & Aktoranforderung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei aktivem Zustand übergibt <code>CrsCtrlAndAccStCtrl</code> Sollwert und Regelstatus an <code>CrsCrtlFree</code>.</li>\n<li><code>CrsCrtlFree</code> ermittelt anhand des von <code>CrsCtrlAndAccObsvrForVehSt</code> bereitgestellten Fahrzeugzustands die Regelabweichung und sendet entsprechende Längsbeschleunigungs- bzw. Verzögerungsanforderungen an <code>Vlc</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>VFB-Unabhängigkeit:</strong> Alle dargestellten Schnittstellen basieren auf standardisierten AUTOSAR Application Interfaces (WPII-Katalog). Die Komponenten kommunizieren ausschließlich über RTE-Sender-Receiver-Interfaces; eine ECU-Allokation ist nicht vorgegeben (SW-Cs können auf einer oder verteilt auf mehreren ECUs deployed werden).</li>\n<li><strong>Variantenmanagement:</strong> Die Architektur zeigt das Pattern zur Variantenbildung: Für Voll-ACC wird die Composition um Radardatenverarbeitung und eine Abstandsregler-SW-C (<code>CrsCtrlAccFree</code> / <code>AccHeadwayCtrl</code>) erweitert, während die HMI-, Zustands- und Beobachterstrukturen weitgehend wiederverwendet werden.</li>\n<li><strong>RTE-Vertrag:</strong></li>\n<li>Datenelemente müssen für deterministisches Verhalten typischerweise mit <code>read-on-demand</code> bzw. zyklisch getakteten Runnables (Task-Perioden meist 10 ms bis 20 ms für Längsführung) konfiguriert werden.</li>\n<li><code>Vlc</code> agiert als Arbiter; <code>CrsCrtlFree</code> darf keine direkten Antriebsstrang- oder Brems-Aktuator-APIs ansteuern, sondern nur normalisierte Beschleunigungswünsche übergeben.</li>\n</ul>"}], "trans": [{"from": "FIG-355025c39493a03a", "to": "FIG-8285daab6fde4628", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umbenennung externer Domänenbezeichnungen an den Schnittstellen:</li>\n<li><code>WPII-10.5 (HMI)</code> ersetzt durch <code>Multimedia Telematics HMI Domain</code></li>\n<li><code>WPII-10.1 (Body)</code> ersetzt durch <code>Body Electronics Domain</code></li>\n<li><code>WPII-10.2 (Powertrain)</code> ersetzt durch <code>Powertrain Domain</code></li>\n</ul>"}, {"from": "FIG-8285daab6fde4628", "to": "FIG-d2d029a5882d44aa", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
